css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  margin-top: 0 !important;
  margin-right: 0 !important;
  margin-bottom: 0 !important;
  margin-left: 0 !important;
  padding: 0 !important;
}

.cd-credit-note,
.cd-credit-note * {
  box-sizing: border-box;
}

.cd-credit-note {
  position: relative;
  width: 210mm;
  height: 297mm;
  margin: 0;
  overflow: hidden;

  --copy-color: #b3b3b3;
  --cd-document-ink: #202020;
  --cd-document-muted: #5f6368;
  --cd-document-border: #202020;
  --cd-document-surface: #f1f1f1;

  color: var(--cd-document-ink);
  background: #fff;
  font-family: "TH Sarabun Document", "Noto Sans Thai", "TH Sarabun New", "TH SarabunPSK", sans-serif;
  font-size: 4.516mm;
  font-weight: 400;
  line-height: 1;

  page-break-after: always;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cd-credit-note.last-page {
  page-break-after: auto;
}

.cd-credit-note .th {
  display: block;
  font-size: 4.516mm;
  line-height: 3.55mm;
  white-space: nowrap;
}

.cd-credit-note .en {
  display: block;
  color: var(--cd-document-muted);
  font-size: 2.75mm;
  line-height: 2.55mm;
  font-weight: 400;
  white-space: nowrap;
}

