/*
  Use actual table borders rather than separately drawn vertical lines.
  This keeps wkhtmltopdf separators straight and continuous.
*/
.cd-credit-note .item-lines {
  position: relative;
  width: 188.32mm;
  margin: 0;
  padding: 0;

  border-collapse: collapse;
  border-spacing: 0;
  table-layout: fixed;

  font-size: 3.75mm;
  line-height: 4.20mm;
}

.cd-credit-note .item-lines col.col-no          { width:  9.00mm; }
.cd-credit-note .item-lines col.col-description { width: 65.00mm; }
.cd-credit-note .item-lines col.col-warehouse   { width: 24.00mm; }
