/* =========================================================
   CREDIT NOTE DESIGN REFINEMENT v2
   Visual-only refinement based on the rendered sample.
   All Credit Note Jinja/data remain unchanged.
   ========================================================= */

/* 1) Give the static intro its own real band instead of overlapping
      the customer/document box and the item table. */
.cd-credit-note .credit-note-intro {
  left: 15.20mm !important;
  top: 106.65mm !important;
  width: 187.00mm !important;
  height: 4.25mm !important;
  padding: 0 !important;
  overflow: hidden !important;
  font-size: 3.90mm !important;
  font-weight: 700 !important;
  line-height: 4.25mm !important;
  white-space: nowrap !important;
}

/* Move the grid down only enough to clear the intro.
   Keep its bottom exactly where the Sales Invoice-style grid ends. */
.cd-credit-note .credit-grid {
  top: 111.20mm !important;
  height: 131.55mm !important;
}

/* 2) Use the same visual font scale as the Sales Invoice.
      Credit Note has more columns, so item text is just slightly smaller
